GRIDS={
"S":(4,3,[("tp","theu")]+[("it",k) for k in ["huongtram","tuithom","nhansam","yensao","luahang","sonphan","vongngoc","thuocanthai"]]),
"A":(4,3,[("it",k) for k in ["tramngoc","boodieu","tramphuong","vongvang","gamto","gamvang","agiao","giaidoc","ngocdungcao","xahuong","hacdinh","botngua"]]),
"B":(4,3,[("it",k) for k in ["tranhco","nghien","dancoc","demgam","vangbac","ngocboi","bienvang","bienngu","thunha","chungcu","hinhnhan","hacdinh"]]),
"W1":(4,4,[("tp",k) for k in ["tranh","bhoa","tho","kinh"]]),
"W2":(4,4,[("tp",k) for k in ["khuc","the","mua","ao"]]),
"W3":(4,2,[("tp",k) for k in ["mon","huong"]]),
}
def cells(g):
    out=[]
    for typ,k in GRIDS[g][2]:
        if typ=="tp": out+= [(f"tp-{k}-b{i+1}",TP[k][i]) for i in range(4)]
        else: out.append((k,IT[k]))
    return out
def prompt(g):
    c,r,_=GRIDS[g];cs=cells(g)
    p=(f"A {c}x{r} sheet of {c*r} separate inventory item icons for a palace game, arranged in exactly {c} columns and {r} rows, "
       "each object isolated and centred in its own equal invisible cell with wide empty margins; objects never touch, overlap or cross into neighbouring cells; "
       "no grid lines, no borders, no frames, no text labels, no captions, no people, no hands, no figures. "
       "Uniform flat plain light grey background over the whole sheet, no shadows on the background except a faint soft contact shadow. "
       "Style: semi-realistic painterly guofeng still life, near-3D realistic rendering with soft natural light and fine detail, rich jewel colours, exactly matching the rendering of the reference image. "
       "Each object seen in 3/4 view from slightly above, filling about 70 percent of its cell, all objects at a similar visual size. ")
    rows=[cs[i*c:(i+1)*c] for i in range(r)]
    for i,row in enumerate(rows):
        if all(k.startswith("tp-") for k,_ in row) and len({k.rsplit('-',1)[0] for k,_ in row})==1:
            p+=f"Row {i+1} shows the SAME kind of handmade work at four quality levels, left to right from crude beginner work to exquisite master treasure, the difference must be obvious: "
        else: p+=f"Row {i+1}, left to right: "
        p+=" ".join(f"({j+1}) {d}." for j,(k,d) in enumerate(row))+" "
    return p
if __name__=="__main__":
    import sys;print(prompt(sys.argv[1]))
